#!/usr/bin/env python3
import urllib.request
import json

# CBSA codes for our three areas
CBSAS = {
    "Portland-Vancouver-Hillsboro, OR-WA": 38900,
    "San Diego-Carlsbad, CA": 41740,
    "Wichita, KS": 48620
}

# Parameter code for Carbon Monoxide
PARAM = 42101

def get_annual_data(cbsa_code, year):
    """Get annual summary data for a CBSA and year"""
    bdate = f"{year}0101"
    edate = f"{year}1231"
    url = f"https://aqs.epa.gov/data/api/annualData/byCBSA?email=test@aqs.api&key=test&param={PARAM}&bdate={bdate}&edate={edate}&cbsa={cbsa_code}"

    try:
        with urllib.request.urlopen(url) as response:
            data = json.loads(response.read().decode())
            return data
    except Exception as e:
        print(f"Error fetching {cbsa_code} for {year}: {e}")
        return None

def check_year_all_good(year):
    """Check if all three CBSAs had all days <=4.4 ppm for a given year"""
    results = {}

    for name, cbsa_code in CBSAS.items():
        data = get_annual_data(cbsa_code, year)

        if not data or data['Header'][0]['status'] != 'Success':
            results[name] = {'qualified': False, 'reason': 'No data or API error', 'max_8hr': None}
            continue

        rows = data.get('Data', [])
        if not rows:
            results[name] = {'qualified': True, 'reason': 'No monitors - trivially passes', 'max_8hr': None}
            continue

        # Look at 8-hour running average data
        eight_hour_maxes = []
        for row in rows:
            if row.get('sample_duration') == '8-HR RUN AVG END HOUR':
                first_max = row.get('first_max_value')
                if first_max is not None:
                    eight_hour_maxes.append(first_max)

        if eight_hour_maxes:
            overall_max = max(eight_hour_maxes)
            qualified = overall_max <= 4.4
            results[name] = {
                'qualified': qualified, 
                'reason': f"Max 8-hr: {overall_max} ppm" if qualified else f"Max 8-hr: {overall_max} ppm EXCEEDS",
                'max_8hr': overall_max
            }
        else:
            # No 8-hour data - might only have 1-hour data
            # Check if we should count this as N/A or qualified
            results[name] = {'qualified': None, 'reason': 'No 8-hour data available', 'max_8hr': None}

    return results

def main():
    print("Checking years 2000-2010 for all-day Good CO levels...")
    print("=" * 60)

    qualifying_years = []

    for year in range(2000, 2011):
        results = check_year_all_good(year)

        all_qualify = True
        has_missing = False

        print(f"\n{year}:")
        for name, info in results.items():
            status = "✓ QUALIFIED" if info['qualified'] else ("✗ NOT QUALIFIED" if info['qualified'] == False else "? MISSING DATA")
            print(f"  {name}: {status} ({info['reason']})")

            if info['qualified'] == False:
                all_qualify = False
            elif info['qualified'] is None:
                has_missing = True

        if all_qualify and not has_missing:
            qualifying_years.append(year)
            print(f"  >>> YEAR {year} QUALIFIES - All areas Good!")

    print("\n" + "=" * 60)
    print(f"\nQualifying years: {qualifying_years}")

    # Write answer
    if qualifying_years:
        answer = ", ".join(str(y) for y in qualifying_years)
    else:
        answer = "none"

    with open('/tmp/pinchbench/6f208671/agent_workspace/answer.txt', 'w') as f:
        f.write(answer)

    print(f"\nAnswer written to answer.txt: {answer}")

if __name__ == "__main__":
    main()
